def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i
    return []

def is_valid_parens(s):
    stack, pairs = [], {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in '([{': stack.append(c)
        elif not stack or stack[-1] != pairs[c]: return False
        else: stack.pop()
    return not stack

def reverse_list(head):
    prev = None
    while head:
        nxt = head.next
        head.next, prev, head = prev, head, nxt
    return prev

def max_subarray(nums):
    best = cur = nums[0]
    for n in nums[1:]:
        cur = max(n, cur + n)
        best = max(best, cur)
    return best

def is_palindrome(s):
    cleaned = [c.lower() for c in s if c.isalnum()]
    return cleaned == cleaned[::-1]

def climb_stairs(n):
    a, b = 1, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def single_number(nums):
    result = 0
    for n in nums:
        result ^= n
    return result

def contains_duplicate(nums):
    seen = set()
    for n in nums:
        if n in seen:
            return True
        seen.add(n)
    return False

def majority_element(nums):
    count, candidate = 0, None
    for n in nums:
        if count == 0: candidate = n
        count += 1 if n == candidate else -1
    return candidate

def move_zeroes(nums):
    write = 0
    for n in nums:
        if n != 0: nums[write], write = n, write + 1
    for i in range(write, len(nums)): nums[i] = 0
    return nums

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]: merged[-1][1] = max(merged[-1][1], end)
        else: merged.append([start, end])
    return merged

def group_anagrams(strs):
    groups = {}
    for s in strs:
        key = ''.join(sorted(s))
        groups.setdefault(key, []).append(s)
    return list(groups.values())

def longest_common_prefix(strs):
    prefix = strs[0] if strs else ''
    for s in strs[1:]:
        while prefix and not s.startswith(prefix): prefix = prefix[:-1]
    return prefix

def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, c in enumerate(s):
        nxt = values[s[i + 1]] if i + 1 < len(s) else 0
        total += -values[c] if values[c] < nxt else values[c]
    return total

def plus_one(digits):
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        digits[i] = 0
    return [1] + digits

def remove_duplicates(nums):
    if not nums: return 0
    write = 1
    for i in range(1, len(nums)):
        if nums[i] != nums[write - 1]: nums[write], write = nums[i], write + 1
    return write

def missing_number(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def fizz_buzz(n):
    result = []
    for i in range(1, n + 1):
        word = 'FizzBuzz' if i % 15 == 0 else 'Fizz' if i % 3 == 0 else 'Buzz' if i % 5 == 0 else str(i)
        result.append(word)
    return result

def hamming_weight(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

def str_str(haystack, needle):
    if not needle:
        return 0
    for i in range(len(haystack) - len(needle) + 1):
        if haystack[i:i + len(needle)] == needle:
            return i
    return -1

def add_binary(a, b):
    result, carry, i, j = [], 0, len(a) - 1, len(b) - 1
    while i >= 0 or j >= 0 or carry:
        total = carry + (int(a[i]) if i >= 0 else 0) + (int(b[j]) if j >= 0 else 0)
        result.append(str(total % 2))
        carry, i, j = total // 2, i - 1, j - 1
    return ''.join(reversed(result))

def title_to_number(column_title):
    result = 0
    for c in column_title:
        result = result * 26 + (ord(c) - ord('A') + 1)
    return result

def is_happy(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d) ** 2 for d in str(n))
    return n == 1

def is_isomorphic(s, t):
    if len(s) != len(t): return False
    forward, backward = {}, {}
    for a, b in zip(s, t):
        if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a: return False
    return True

def word_pattern(pattern, s):
    words = s.split()
    if len(pattern) != len(words): return False
    forward, backward = {}, {}
    for a, b in zip(pattern, words):
        if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a: return False
    return True

