def is_symmetric(root):
    def mirror(a, b):
        if not a or not b: return a == b
        return a.val == b.val and mirror(a.left, b.right) and mirror(a.right, b.left)
    return mirror(root, root) if root else True

def diameter_of_binary_tree(root):
    def walk(node):
        if not node: return 0, 0
        (lh, lb), (rh, rb) = walk(node.left), walk(node.right)
        return 1 + max(lh, rh), max(lb, rb, lh + rh)
    return walk(root)[1]

def is_balanced(root):
    def height(node):
        if not node: return 0
        l, r = height(node.left), height(node.right)
        return -1 if min(l, r) < 0 or abs(l - r) > 1 else 1 + max(l, r)
    return height(root) >= 0

def has_path_sum(root, target):
    if not root: return False
    if not root.left and not root.right: return root.val == target
    return has_path_sum(root.left, target - root.val) or has_path_sum(root.right, target - root.val)

def lowest_common_ancestor(root, p, q):
    while root:
        if p.val < root.val and q.val < root.val: root = root.left
        elif p.val > root.val and q.val > root.val: root = root.right
        else: return root
    return None

def search_insert(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        lo, hi = (mid + 1, hi) if nums[mid] < target else (lo, mid)
    return lo

def max_area(height):
    left, right, best = 0, len(height) - 1, 0
    while left < right:
        best = max(best, min(height[left], height[right]) * (right - left))
        left, right = (left + 1, right) if height[left] < height[right] else (left, right - 1)
    return best
